// Keep open CanadaBuys notices delivered to (or bought from) the provinces you list in Settings,
// plus national "*Canada" ones (tagged CANADA so a subscriber can opt in). One clean item per tender.
const REGIONS = {
  NS: ['nova scotia', 'halifax', 'dartmouth', 'greenwood', 'shearwater', 'sydney', 'truro', 'kentville', 'yarmouth', 'bridgewater', 'antigonish', 'new glasgow'],
  NB: ['new brunswick', 'oromocto', 'gagetown', 'fredericton', 'moncton', 'saint john', 'shediac', 'bathurst', 'miramichi', 'edmundston', 'dieppe'],
  PE: ['prince edward island', 'charlottetown', 'summerside'],
  NL: ['newfoundland', "st. john's", 'st johns', 'gander', 'goose bay', 'corner brook', 'labrador'],
  QC: ['quebec', 'québec', 'montreal', 'montréal', 'gatineau', 'laval'],
  ON: ['ontario', 'ottawa', 'toronto', 'kingston', 'hamilton', 'london', 'sudbury', 'thunder bay'],
  MB: ['manitoba', 'winnipeg', 'brandon'],
  SK: ['saskatchewan', 'regina', 'saskatoon'],
  AB: ['alberta', 'calgary', 'edmonton', 'red deer'],
  BC: ['british columbia', 'vancouver', 'victoria', 'esquimalt', 'kelowna', 'nanaimo'],
  YT: ['yukon', 'whitehorse'], NT: ['northwest territories', 'yellowknife'], NU: ['nunavut', 'iqaluit'],
  CANADA: ['canada'],
};
const WANT = String($('Settings').first().json.provinces || 'NS,NB,PE,NL').split(',').map((x) => x.trim().toUpperCase()).concat(['CANADA']);
const CATEGORY = { GD: 'Goods', SRV: 'Services', CNST: 'Construction', SRVTGD: 'Services related to goods' };
const now = Date.now(), seen = new Set(), out = [];
const clean = (s) => String(s || '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
for (const it of $input.all()) {
  const r = {};
  for (const k of Object.keys(it.json || {})) r[k.replace(/^﻿/, '').replace(/^"|"$/g, '').trim()] = it.json[k];
  const g = (k) => String(r[k] == null ? '' : r[k]).trim();
  const id = g('referenceNumber-numeroReference');
  if (!id || seen.has(id)) continue;
  if (g('tenderStatus-appelOffresStatut-eng') && g('tenderStatus-appelOffresStatut-eng') !== 'Open') continue;
  const closing = g('tenderClosingDate-appelOffresDateCloture');
  if (closing && Date.parse(closing) && Date.parse(closing) < now) continue;
  let places = g('regionsOfDelivery-regionsLivraison-eng').split(/[\r\n]+/).map((x) => x.replace(/^\*/, '').trim()).filter(Boolean);
  if (!places.length) places = [g('contractingEntityAddressProvince-entiteContractanteAdresseProvince-eng'), g('contractingEntityAddressCity-entiteContractanteAdresseVille-eng')].filter(Boolean);
  const codes = [];
  for (const p of places) {
    const pl = p.toLowerCase();
    for (const code of Object.keys(REGIONS)) {
      if (codes.includes(code) || !WANT.includes(code)) continue;
      if (REGIONS[code].some((n) => pl === n || pl.startsWith(n))) codes.push(code);
    }
  }
  if (!codes.length) continue;
  seen.add(id);
  const title = clean(g('title-titre-eng'));
  const description = clean(g('tenderDescription-descriptionAppelOffres-eng')).slice(0, 700);
  const gsin = clean(g('gsinDescription-nibsDescription-eng').replace(/\*/g, ' '));
  const unspsc = clean(g('unspscDescription-eng').replace(/\*/g, ' '));
  const cat = g('procurementCategory-categorieApprovisionnement').split(/[\r\n]+/).map((x) => CATEGORY[x.replace(/^\*/, '').trim()] || x.replace(/^\*/, '').trim()).filter(Boolean).join(', ');
  const solicitation = g('solicitationNumber-numeroSollicitation');
  const url = g('noticeURL-URLavis-eng') || 'https://canadabuys.canada.ca/en/tender-opportunities?search_filter=' + encodeURIComponent(solicitation || id);
  out.push({ json: { tender_id: id, title, description, category: cat, buyer: g('contractingEntityName-nomEntitContractante-eng'),
    published: g('publicationDate-datePublication'), closing_date: closing, regions: codes, region_names: places.join(', '), url,
    search_text: (title + ' ' + description + ' ' + gsin + ' ' + unspsc + ' ' + cat).toLowerCase() } });
}
return out;

// Your subscribers. Replace these examples, or swap this node for Google Sheets / a data table.
// keywords: comma list of word starts ("landscap" catches landscaping). regions: NS,NB,PE,NL,QC,ON,MB,SK,AB,BC,YT,NT,NU,CANADA
return [
  { name: 'Sample Landscaping', email: 'owner@example.com', keywords: 'landscap, snow, grounds', regions: 'NS,CANADA', active: true },
  { name: 'Sample Electric', email: 'office@example.com', keywords: 'electric, lighting, generator', regions: 'NS,NB', active: true },
].map((s) => ({ json: s }));

// Pair every subscriber with every tender that matches one of their keywords AND one of their regions.
// Keywords match at the start of a word: "landscap" catches "landscaping", "electric" catches "electrical".
// Tenders already sent to a subscriber are skipped (remembered in this workflow's static data,
// which n8n keeps between production runs; manual test runs do not save it).
const tenders = $input.all().map((i) => i.json);
const subs = $('Subscribers').all().map((i) => i.json).filter((s) => s && s.email && s.active !== false);
const sent = $getWorkflowStaticData('global'); sent.keys = sent.keys || {};
const esc = (s) => s.replace(/[.*+?^$()|[\]\\{}]/g, '\\$&');
const out = [];
for (const s of subs) {
  const email = String(s.email).trim().toLowerCase();
  const kws = String(s.keywords || '').split(',').map((k) => k.trim().toLowerCase()).filter(Boolean);
  const regions = String(s.regions || '').split(',').map((r) => r.trim().toUpperCase()).filter(Boolean);
  if (!kws.length || !regions.length) continue;
  const tests = kws.map((k) => ({ k, re: new RegExp('(^|[^a-z0-9])' + esc(k)) }));
  for (const t of tenders) {
    const key = email + '|' + t.tender_id;
    if (sent.keys[key]) continue;
    const regionHit = (t.regions || []).filter((r) => regions.includes(r));
    if (!regionHit.length) continue;
    const hits = tests.filter((x) => x.re.test(t.search_text || '')).map((x) => x.k);
    if (!hits.length) continue;
    out.push({ json: { seen_key: key, subscriber_name: s.name || '', subscriber_email: email, matched_keywords: hits.join(', '),
      tender_id: t.tender_id, title: t.title, category: t.category, buyer: t.buyer, closing_date: t.closing_date, region_names: t.region_names, url: t.url } });
  }
}
return out;

// One digest per subscriber: soonest-closing first, capped at max_per_digest.
// Anything over the cap is not marked as sent, so it rolls into the next digest.
const settings = $('Settings').first().json;
const MAX = Number(settings.max_per_digest || 30);
const h = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const day = (d) => (String(d || '').slice(0, 10) || 'not stated');
const groups = {};
for (const it of $input.all()) { const m = it.json; (groups[m.subscriber_email] = groups[m.subscriber_email] || { name: m.subscriber_name, rows: [] }).rows.push(m); }
const today = new Date().toISOString().slice(0, 10);
const sent = $getWorkflowStaticData('global'); sent.keys = sent.keys || {};
const out = [];
for (const email of Object.keys(groups)) {
  const g = groups[email];
  const rows = g.rows.sort((a, b) => String(a.closing_date || '9999').localeCompare(String(b.closing_date || '9999')));
  const shown = rows.slice(0, MAX), extra = rows.length - shown.length;
  const items = shown.map((t) => '<tr><td style="padding:10px 8px;border-bottom:1px solid #e5e5e5;vertical-align:top"><a href="' + h(t.url) + '" style="color:#0b5cad;font-weight:600;text-decoration:none">' + h(t.title) + '</a>' +
    '<div style="color:#555;font-size:13px;margin-top:4px">' + h(t.buyer) + (t.category ? ' &middot; ' + h(t.category) : '') + '</div>' +
    '<div style="color:#777;font-size:12px;margin-top:4px">Delivery: ' + h(t.region_names) + ' &middot; Matched: ' + h(t.matched_keywords) + '</div></td>' +
    '<td style="padding:10px 8px;border-bottom:1px solid #e5e5e5;vertical-align:top;white-space:nowrap;font-size:13px">' + h(day(t.closing_date)) + '</td></tr>').join('');
  const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;color:#222"><h2 style="margin:0 0 4px">' + shown.length + ' new tender' + (shown.length === 1 ? '' : 's') + ' for you</h2>' +
    '<p style="margin:0 0 16px;color:#555">Hi ' + h(g.name || 'there') + ', these public tenders match your trades and regions. Soonest closing first.</p>' +
    '<table style="border-collapse:collapse;width:100%"><tr><th align="left" style="padding:6px 8px;border-bottom:2px solid #222">Tender</th><th align="left" style="padding:6px 8px;border-bottom:2px solid #222">Closes</th></tr>' + items + '</table>' +
    (extra > 0 ? '<p style="color:#555">' + extra + ' more matched and will come in your next digest.</p>' : '') +
    '<p style="color:#888;font-size:12px;margin-top:24px">Source: CanadaBuys open tender notices (Open Government Licence - Canada). Always confirm details and deadlines on the official notice.<br>' +
    h(settings.sender_name) + (settings.postal_address ? ' &middot; ' + h(settings.postal_address) : '') + '<br>To stop these emails, reply with STOP.</p></div>';
  // Mark as sent only in production runs, so test runs can be repeated.
  if ($execution.mode !== 'manual') for (const t of shown) sent.keys[t.seen_key] = today;
  out.push({ json: { to: email, subject: shown.length + ' new tender' + (shown.length === 1 ? '' : 's') + ' matching your trades (' + today + ')', html, tender_count: shown.length, held_for_next_digest: extra } });
}
return out;
